// P7 gallery: a sleeping porch on the upper deck, two units divided by the brick pier x89..90.
// Inner air box [85,8,7, 94,10,8]. Each unit has its own gallery door (x88 and x91, z9, y8..9); the cells in front
// of them (x88 z8, x91 z8) stay clear. Per unit: one bed with its head against the house wall (z9, y8), a barrel
// nightstand with a flower pot, a chair on the front edge, and a hanging lantern. The bed heads are against solid wall
// cells, never a window (the windows sit at y9..10 on z9).
import { Grid, layers, bed, B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { chair, hanging_lantern } from "../vocab.mjs";

export function build(g) {
  // Floor layer (y8): the beds' feet on z7, heads on z8, barrels as nightstands, chairs on the front edge.
  // Legend: C = chair seat (drawn by chair()), B = barrel, letters for bed halves are placed by bed().
  layers(g, [85, 8, 7], {
    B: ["barrel", { facing: "up" }],
  }, [
    // z7: x85..94
    ["   C  ..  C  "],
    // z8: x85..94
    ["B        B  "],
  ]);
  // Layer y9: flower pots on the nightstand barrels.
  layers(g, [85, 9, 8], { P: "flower_pot" }, [
    ["P         P"],
  ]);
  // Beds: west unit (red) and east unit (orange), heads at z8 against the house wall z9.
  bed(g, [86, 8, 7], "south", "red");
  bed(g, [93, 8, 7], "south", "orange");
  // Chairs on the front edge (sitters look north over the lane).
  chair(g, 87, 8, 7, "north");
  chair(g, 92, 8, 7, "north");
  // Lanterns hang from the roof over each unit, clear of the doorways (x88, x91).
  hanging_lantern(g, 87, 10, 8);
  hanging_lantern(g, 92, 10, 8);
}

